mapper.select:
SELECT * FROM ( SELECT DETAIL_DIST, BOOKSET_ID AS bookSetId, ( SELECT bb.ACCT_SUBJECT_ID FROM BOK_BOOKSET bb WHERE bb.BOOKSET_ID = BOK_VAL_TABLE_DATA.BOOKSET_ID) AS prodId, TO_CHAR(VAL_DATE,'YYYY-MM-DD') AS valueDate, NVL(MARKET_VALUE, to_number(REGEXP_REPLACE(BOK_VAL_TABLE_DATA.SUBJECT_NAME,'[^0-9|.]',''))) MARKET_VALUE FROM BOK_VAL_TABLE_DATA WHERE BOOKSET_ID IN ( SELECT bookset_id FROM BOK_BOOKSET WHERE ACCT_MODE = '01') AND BOOKSET_ID in
#{item, jdbcType=VARCHAR}
AND VAL_DATE = #{exeDate, jdbcType=TIMESTAMP} AND DETAIL_DIST IN ('02','05','06','07','08','17') ) PIVOT ( MAX(MARKET_VALUE) FOR DETAIL_DIST IN ( '02' AS prodAllAmt, '17' AS totalValue, '05' AS dailyAssetAllValue, '06' AS dailyAllDebt, '08' AS unitValue) ) ORDER BY valueDate

select 
fin.ACCR_STR_DATE
 from 
FIN_FLOAT_ACCRUAL_SCHE fin
where CASH_ID in (
select CASH_ID
from FIN_CASH_INFO  f
where  f.CASH_TYPE_2=#{type2, jdbcType=VARCHAR}
and f.FINPROD_ID=#{prodId, jdbcType=VARCHAR}
)
and fin.ACCR_STR_DATE <#{valDate, jdbcType=DATE}
ORDER BY fin.ACCR_STR_DATE DESC
